**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <vector>
using namespace std;

string wspolnyPrefiks(const string& a, const string& b) {
    string wynik = "";
    int minLen = min((int)a.length(), (int)b.length());
    for (int i = 0; i < minLen; i++) {
        if (a[i] == b[i]) wynik += a[i];
        else break;
    }
    return wynik;
}

int main() {
    ifstream plik("napisy.txt");
    string s;
    vector<string> napisy;
    while (plik >> s) {
        napisy.push_back(s);
    }
    string prefiks = napisy[0];
    for (int i = 1; i < (int)napisy.size(); i++) {
        prefiks = wspolnyPrefiks(prefiks, napisy[i]);
    }
    if (prefiks.empty()) {
        cout << "Wspolny prefiks wszystkich: (brak) (dlugosc: 0)" << endl;
    } else {
        cout << "Wspolny prefiks wszystkich: " << prefiks << " (dlugosc: " << prefiks.length() << ")" << endl;
    }
    cout << "Pary:" << endl;
    for (int i = 0; i < (int)napisy.size() - 1; i++) {
        string wp = wspolnyPrefiks(napisy[i], napisy[i + 1]);
        cout << napisy[i] << " i " << napisy[i + 1] << ": " << wp << endl;
    }
    return 0;
}
```

**Wyjasnienie**: Funkcja `wspolnyPrefiks` porownuje znaki na tych samych pozycjach i buduje prefiks do momentu pierwszej roznicy. Wspolny prefiks calej listy wyznaczamy iteracyjnie, redukujac prefiks z kazdym kolejnym napisem.

Weryfikacja:
Spisujem znaki na pozycjach kluczowych:
- przedstawienie: p-r-z-e-d-s-t-a-w-i-e-n-i-e
- przedmiot:      p-r-z-e-d-m-i-o-t
- przedszkolak:   p-r-z-e-d-s-z-k-o-l-a-k
- przepis:        p-r-z-e-p-i-s
- przekaznik:     p-r-z-e-k-a-z-n-i-k
- przelot:        p-r-z-e-l-o-t
- przypadek:      p-r-z-y-p-a-d-e-k
- pracownik:      p-r-a-c-o-w-n-i-k

Wspolny prefiks wszystkich (redukcja):
- Start: "przedstawienie"
- + przedmiot: poz 5: s!=m -> "przed"
- + przedszkolak: poz 5: nie badamy dalej bo prefiks="przed" (5 znakow), przedszkolak[0..4]="przed" -> "przed"
- + przepis: poz 4: d!=p -> "prze"
- + przekaznik: prze==prze -> "prze"
- + przelot: prze==prze -> "prze"
- + przypadek: poz 3: e!=y -> "prz"
- + pracownik: poz 2: z!=a -> "pr"
Wynik: "pr" (dlugosc 2)

Pary sasiednie:
- przedstawienie i przedmiot: p,r,z,e,d (poz 5: s!=m) -> "przed"
- przedmiot i przedszkolak: p,r,z,e,d (poz 5: m!=s) -> "przed"
- przedszkolak i przepis: p,r,z,e (poz 4: d!=p) -> "prze"
- przepis i przekaznik: p,r,z,e (poz 4: p!=k) -> "prze"
- przekaznik i przelot: p,r,z,e (poz 4: k!=l) -> "prze"
- przelot i przypadek: p,r,z (poz 3: e!=y) -> "prz"
- przypadek i pracownik: p,r (poz 2: z!=a) -> "pr"
